const baseLink=(label,view)=>el('a',label,{href:'#'+view,'data-view':view,class:'am-button am-secondary'});
function icon(name){if(['people','note','cup'].includes(name))return sharedIcon(name);const p={leaf:'M5 21c-3-12 4-18 16-18-1 11-6 16-14 13 M5 21L17 7 M8 15l-1-6 M11 12l6 1',photo:'M3 4h18v16H3z M3 17l6-6 4 4 3-3 5 5 M15 7h.1',bridge:'M2 20V8 M22 20V8 M7 20V8 M17 20V8 M2 14c7-7 13-7 20 0 M2 18h20',sprout:'M12 22V12 M12 13C3 13 2 5 3 3c7 0 9 4 9 10 M12 16c0-9 6-12 10-11-1 7-4 10-10 11'}[name];const svg=sharedIcon('note');svg.querySelector('path').setAttribute('d',p||'M12 3v18 M3 12h18');return svg;}
